{
  "units": [
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "A generator may accumulate without a permit or interim status and without complying with 40 CFR parts 124, 264 through 267, and 270 as much as 55 gallons of non-acute hazardous waste and/or either one quart of liquid acute hazardous waste listed in § 261.31 or § 261.33(e) or 1 kg (2.2 lbs) of solid acute hazardous waste listed in § 261.31 or § 261.33(e) in containers at or near any point of generation where wastes initially accumulate under the control of the operator of the process generating the waste, provided all conditions for exemption in § 262.15 are met."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "alternative",
      "meaning": "A generator may comply with the conditions for exemption in § 262.15 instead of complying with the conditions for exemption in § 262.16(b) or § 262.17(a), except as required in § 262.15(a)(7) and (8)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, if a container holding hazardous waste is not in good condition or begins to leak, the generator must immediately transfer the hazardous waste to a container in good condition that does not leak, or immediately transfer and manage the waste in a central accumulation area operated in compliance with § 262.16(b) or § 262.17(a)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, the generator must use a container made of or lined with materials that will not react with, and are otherwise compatible with, the hazardous waste to be accumulated, so that the ability of the container to contain the waste is not impaired."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F013"],
      "kind": "prohibition",
      "meaning": "As a condition for exemption for satellite accumulation, incompatible wastes, or incompatible wastes and materials (see appendix V of part 265 for examples), must not be placed in the same container, unless 40 CFR 265.17(b) is complied with."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F013"],
      "kind": "prohibition",
      "meaning": "As a condition for exemption for satellite accumulation, hazardous waste must not be placed in an unwashed container that previously held an incompatible waste or material (see appendix V of part 265 for examples), unless 40 CFR 265.17(b) is complied with."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a container holding hazardous waste that is incompatible with any waste or other materials accumulated nearby in other containers must be separated from the other materials or protected from them by any practical means."
    },
    {
      "quote_ref": "F020:F021",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a container holding hazardous waste must be closed at all times during accumulation, except when adding, removing, or consolidating waste."
    },
    {
      "quote_ref": "F022:F024",
      "scope_refs": ["F013", "F020"],
      "kind": "exception",
      "meaning": "As an exception to the requirement that a container holding hazardous waste must be closed at all times during accumulation, the container may be open when temporary venting is necessary for the proper operation of equipment or to prevent dangerous situations, such as build-up of extreme pressure."
    },
    {
      "quote_ref": "F025:F026",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a generator must mark or label its container with the words “Hazardous Waste”."
    },
    {
      "quote_ref": "F027",
      "scope_refs": ["F013", "F025"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a generator must mark or label its container with an indication of the hazards of the contents (examples include, but are not limited to, applicable hazardous waste characteristics [ignitable, corrosive, reactive, toxic]; hazard communication consistent with DOT requirements at 49 CFR part 172 subpart E or F; an OSHA hazard statement or pictogram under 29 CFR 1910.1200; or an NFPA code 704 chemical hazard label)."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F013", "F028"],
      "kind": "alternative",
      "meaning": "A generator accumulating either acute hazardous waste listed in § 261.31 or § 261.33(e) or non-acute hazardous waste at or near any point of generation in excess of the amounts listed in § 262.15(a) must, as an alternative, comply within three consecutive calendar days with the applicable central accumulation area regulations in § 262.16(b) or § 262.17(a)."
    },
    {
      "quote_ref": "F030:F033",
      "scope_refs": ["F013", "F028"],
      "kind": "alternative",
      "meaning": "A generator accumulating either acute hazardous waste listed in § 261.31 or § 261.33(e) or non-acute hazardous waste at or near any point of generation in excess of the amounts listed in § 262.15(a) must, as an alternative, remove the excess from the satellite accumulation area within three consecutive calendar days to either a central accumulation area operated under § 262.16(b) or § 262.17(a), an on-site interim status or permitted TSDF, or an off-site designated facility."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F013", "F028"],
      "kind": "requirement",
      "meaning": "During the three-consecutive-calendar-day period following accumulation in excess of the allowed limits, the generator must continue to comply with § 262.15(a)(1) through (5) and must mark or label the container(s) holding the excess accumulation of hazardous waste with the date the excess amount began accumulating."
    },
    {
      "quote_ref": "F035",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "All satellite accumulation areas operated by a small quantity generator must meet the preparedness and prevention regulations of § 262.16(b)(8) and emergency procedures of § 262.16(b)(9)."
    },
    {
      "quote_ref": "F036",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "All satellite accumulation areas operated by a large quantity generator must meet the Preparedness, Prevention and Emergency Procedures in 40 CFR part 262 subpart M."
    },
    {
      "quote_ref": "F037",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph (b) is marked as reserved, containing no substantive requirements."
    }
  ]
}
